-- =============================================================================
-- SALingo — Vocabulary Engine v2: schema expansion + content pool.
-- Additive migration: run in the Supabase SQL Editor, after vocabulary.sql
-- and vocabulary-b2-c1-c2.sql. Safe to re-run (ON CONFLICT DO NOTHING;
-- ALTER ... ADD COLUMN IF NOT EXISTS).
--
-- Adds lexical-knowledge columns (definition, multiple examples, synonyms,
-- antonyms, collocations, register, topic, word-family links, polysemy
-- sense, common mistake) so a word is taught as WORD + MEANING + CONTEXT +
-- COLLOCATION + REGISTER + NUANCE, not just word -> translation (see
-- DEVELOPMENT_REPORT.md § Vocabulary Engine).
-- =============================================================================

alter table public.vocabulary_words add column if not exists part_of_speech text;
alter table public.vocabulary_words add column if not exists definition text;
alter table public.vocabulary_words add column if not exists examples text[];
alter table public.vocabulary_words add column if not exists synonyms text[];
alter table public.vocabulary_words add column if not exists antonyms text[];
alter table public.vocabulary_words add column if not exists collocations text[];
alter table public.vocabulary_words add column if not exists register text check (register in ('casual', 'neutral', 'formal'));
alter table public.vocabulary_words add column if not exists topic text;
alter table public.vocabulary_words add column if not exists related_words text[];
alter table public.vocabulary_words add column if not exists sense text;
alter table public.vocabulary_words add column if not exists common_mistake text;

create index if not exists vocabulary_words_topic_idx on public.vocabulary_words (topic);

-- -----------------------------------------------------------------------------
-- A1 — everyday basics not yet covered: greetings, numbers, colors, clothes,
-- time, basic verbs/adjectives, places, transportation, routines.
-- -----------------------------------------------------------------------------
on conflict (id) do nothing;

-- -----------------------------------------------------------------------------
-- A2 — shopping, travel, health, hobbies, work, education, relationships,
-- weather, technology, city, phrasal verbs.
-- -----------------------------------------------------------------------------
on conflict (id) do nothing;

-- -----------------------------------------------------------------------------
-- B1 — workplace, communication, emotions, environment, idioms, phrasal
-- verbs, collocations. Synonym/antonym nuance sets start here.
-- -----------------------------------------------------------------------------
on conflict (id) do nothing;

-- -----------------------------------------------------------------------------
-- B2 — professional English, customer service, business, negotiation,
-- leadership, tech, economics, media, psychology, law, finance. Advanced
-- phrasal verbs, collocations, idioms, formal vocabulary, word formation.
-- -----------------------------------------------------------------------------
on conflict (id) do nothing;

-- -----------------------------------------------------------------------------
-- C1 — academic/professional English, business, economics, psychology,
-- technology, ethics, communication, social issues. Collocations, idioms,
-- discourse markers, nuanced synonyms, abstract vocabulary, register.
-- -----------------------------------------------------------------------------
on conflict (id) do nothing;

-- -----------------------------------------------------------------------------
-- C2 — nuance, register, precision, sophisticated connectors, rhetorical
-- and academic vocabulary. Includes the "big" intensity ladder from the
-- spec brief (big/large/substantial/considerable/enormous/massive/
-- significant) so Register/Nuance Challenge has a real set to test.
-- -----------------------------------------------------------------------------
on conflict (id) do nothing;

-- -----------------------------------------------------------------------------
-- Polysemy set (§16) — the same headword taught across its distinct senses,
-- each a separate row (own id, definition, example, translation) so the
-- engine can present them as different "cards" and Nuance Challenge can
-- contrast them. B2/C1, per the spec's emphasis for these levels.
-- -----------------------------------------------------------------------------
on conflict (id) do nothing;

-- -----------------------------------------------------------------------------
-- Call center / customer service career-prep vocabulary (§34) — feeds
-- Vocabulary, and is reused by Interview Prep / Roleplay via shared terms.
-- -----------------------------------------------------------------------------
on conflict (id) do nothing;

-- -----------------------------------------------------------------------------
-- Phrasal verb library (§18) — remaining common set not already covered
-- above (find out, bring up, come across as already exist; this adds the
-- rest with meaning + context + activity-ready definition).
-- -----------------------------------------------------------------------------
on conflict (id) do nothing;
