values
  ('en-vocab-v2-hello', 'en', 'Hello', 'Hola', '/həˈloʊ/', 'Hello, how are you?', 'Daily Life', 'A1', 'interjection', 'A greeting used when meeting someone.', ARRAY['Hello, how are you?', 'She said hello to her neighbor.', 'Hello! Is anyone home?'], 'neutral', 'Greetings'),
  ('en-vocab-v2-goodbye', 'en', 'Goodbye', 'Adiós', '/ɡʊdˈbaɪ/', 'We waved and said goodbye.', 'Daily Life', 'A1', 'interjection', 'A word said when leaving or ending a conversation.', ARRAY['We waved and said goodbye.', 'He said goodbye before boarding the train.', 'Goodbye! See you tomorrow.'], 'neutral', 'Greetings'),
  ('en-vocab-v2-please', 'en', 'Please', 'Por favor', '/pliːz/', 'Please close the door.', 'Daily Life', 'A1', 'adverb', 'Used to make a request more polite.', ARRAY['Please close the door.', 'Can I have some water, please?', 'Please wait a moment.'], 'formal', 'Greetings'),
  ('en-vocab-v2-mother', 'en', 'Mother', 'Madre', '/ˈmʌð.ɚ/', 'My mother works at a hospital.', 'Family', 'A1', 'noun', 'A female parent.', ARRAY['My mother works at a hospital.', 'She looks like her mother.', 'His mother called him twice today.'], 'neutral', 'Family'),
  ('en-vocab-v2-father', 'en', 'Father', 'Padre', '/ˈfɑː.ðɚ/', 'His father is a teacher.', 'Family', 'A1', 'noun', 'A male parent.', ARRAY['His father is a teacher.', 'I asked my father for advice.', 'Their father picks them up from school.'], 'neutral', 'Family'),
  ('en-vocab-v2-one', 'en', 'One', 'Uno', '/wʌn/', 'I have one brother.', 'Daily Life', 'A1', 'number', 'The number 1.', ARRAY['I have one brother.', 'Give me one minute.', 'There is only one seat left.'], 'neutral', 'Numbers'),
  ('en-vocab-v2-ten', 'en', 'Ten', 'Diez', '/ten/', 'The store closes at ten.', 'Daily Life', 'A1', 'number', 'The number 10.', ARRAY['The store closes at ten.', 'We waited for ten minutes.', 'She scored ten out of ten.'], 'neutral', 'Numbers'),
  ('en-vocab-v2-red', 'en', 'Red', 'Rojo', '/red/', 'She bought a red dress.', 'Daily Life', 'A1', 'adjective', 'The color of blood or a ripe tomato.', ARRAY['She bought a red dress.', 'The light turned red.', 'His face went red with embarrassment.'], 'neutral', 'Colors'),
  ('en-vocab-v2-blue', 'en', 'Blue', 'Azul', '/bluː/', 'The sky is blue today.', 'Daily Life', 'A1', 'adjective', 'The color of a clear sky.', ARRAY['The sky is blue today.', 'He wore a blue shirt.', 'They painted the room blue.'], 'neutral', 'Colors'),
  ('en-vocab-v2-shirt', 'en', 'Shirt', 'Camisa', '/ʃɝːt/', 'He ironed his shirt before work.', 'Daily Life', 'A1', 'noun', 'A piece of clothing worn on the upper body.', ARRAY['He ironed his shirt before work.', 'I need a new shirt for the interview.', 'Her shirt was covered in paint.'], 'neutral', 'Clothes'),
  ('en-vocab-v2-shoes', 'en', 'Shoes', 'Zapatos', '/ʃuːz/', 'Take off your shoes at the door.', 'Daily Life', 'A1', 'noun', 'Footwear worn to protect and cover the feet.', ARRAY['Take off your shoes at the door.', 'These shoes are very comfortable.', 'She bought new shoes for the trip.'], 'neutral', 'Clothes'),
  ('en-vocab-v2-monday', 'en', 'Monday', 'Lunes', '/ˈmʌn.deɪ/', 'The meeting is on Monday.', 'Work', 'A1', 'noun', 'The first day of the working week.', ARRAY['The meeting is on Monday.', 'I start my new job on Monday.', 'We always clean the house on Monday.'], 'neutral', 'Days'),
  ('en-vocab-v2-january', 'en', 'January', 'Enero', '/ˈdʒæn.ju.er.i/', 'She was born in January.', 'Daily Life', 'A1', 'noun', 'The first month of the year.', ARRAY['She was born in January.', 'We usually travel in January.', 'The sale starts in January.'], 'neutral', 'Months'),
  ('en-vocab-v2-clock', 'en', 'Clock', 'Reloj', '/klɑːk/', 'The clock on the wall stopped.', 'Daily Life', 'A1', 'noun', 'A device that shows the time.', ARRAY['The clock on the wall stopped.', 'I set the clock to seven.', 'The kitchen clock is always slow.'], 'neutral', 'Time'),
  ('en-vocab-v2-go', 'en', 'Go', 'Ir', '/ɡoʊ/', 'I go to work by bus.', 'Daily Life', 'A1', 'verb', 'To move or travel to a place.', ARRAY['I go to work by bus.', 'We go to the gym on Tuesdays.', 'She goes to school every morning.'], 'neutral', 'Basic Verbs'),
  ('en-vocab-v2-eat', 'en', 'Eat', 'Comer', '/iːt/', 'We eat dinner at eight.', 'Food', 'A1', 'verb', 'To put food in your mouth and swallow it.', ARRAY['We eat dinner at eight.', 'She eats breakfast quickly.', 'Did you eat lunch already?'], 'neutral', 'Basic Verbs'),
  ('en-vocab-v2-happy', 'en', 'Happy', 'Feliz', '/ˈhæp.i/', 'She looked happy at the party.', 'Daily Life', 'A1', 'adjective', 'Feeling or showing pleasure.', ARRAY['She looked happy at the party.', 'I''m happy with my new job.', 'They were happy to see their friends.'], 'neutral', 'Basic Adjectives'),
  ('en-vocab-v2-tired', 'en', 'Tired', 'Cansado/a', '/taɪɚd/', 'He felt tired after the trip.', 'Health', 'A1', 'adjective', 'Needing rest or sleep.', ARRAY['He felt tired after the trip.', 'I''m too tired to cook tonight.', 'The children were tired after school.'], 'neutral', 'Basic Adjectives'),
  ('en-vocab-v2-park', 'en', 'Park', 'Parque', '/pɑːrk/', 'We walked in the park.', 'Daily Life', 'A1', 'noun', 'A public area with grass and trees for recreation.', ARRAY['We walked in the park.', 'The kids play in the park after school.', 'There''s a park near my house.'], 'neutral', 'Places'),
  ('en-vocab-v2-bus', 'en', 'Bus', 'Autobús', '/bʌs/', 'I take the bus to work.', 'Travel', 'A1', 'noun', 'A large road vehicle that carries passengers.', ARRAY['I take the bus to work.', 'The bus was late today.', 'We missed the last bus home.'], 'neutral', 'Transportation'),
  ('en-vocab-v2-wake-up', 'en', 'Wake up', 'Despertarse', '/weɪk ʌp/', 'I wake up at six every day.', 'Daily Life', 'A1', 'phrasal verb', 'To stop sleeping.', ARRAY['I wake up at six every day.', 'She woke up late this morning.', 'The noise woke him up.'], 'neutral', 'Daily Routines')
