values
  ('en-vocab-v2-receipt', 'en', 'Receipt', 'Recibo', '/rɪˈsiːt/', 'Keep the receipt in case you need a refund.', 'Shopping', 'A2', 'noun', 'A printed proof of purchase.', ARRAY['Keep the receipt in case you need a refund.', 'She lost her receipt at the mall.', 'Can I get a receipt, please?'], NULL, 'neutral', 'Shopping'),
  ('en-vocab-v2-discount', 'en', 'Discount', 'Descuento', '/ˈdɪs.kaʊnt/', 'We got a 20% discount on shoes.', 'Shopping', 'A2', 'noun', 'A reduction in the usual price.', ARRAY['We got a 20% discount on shoes.', 'Students receive a discount here.', 'The discount only applies today.'], ARRAY['deal', 'markdown'], 'neutral', 'Shopping'),
  ('en-vocab-v2-try-on', 'en', 'Try on', 'Probarse (ropa)', '/traɪ ɒn/', 'Can I try on this jacket?', 'Shopping', 'A2', 'phrasal verb', 'To put on clothing to see if it fits.', ARRAY['Can I try on this jacket?', 'She tried on three pairs of jeans.', 'Try it on before you buy it.'], NULL, 'neutral', 'Shopping'),
  ('en-vocab-v2-book-flight', 'en', 'Book (a flight)', 'Reservar (un vuelo)', '/bʊk/', 'I booked a flight to Lima.', 'Travel', 'A2', 'verb', 'To arrange to have a seat, room, or service in advance.', ARRAY['I booked a flight to Lima.', 'We booked our hotel online.', 'Have you booked the tickets yet?'], ARRAY['reserve'], 'neutral', 'Travel'),
  ('en-vocab-v2-delay', 'en', 'Delay', 'Retraso', '/dɪˈleɪ/', 'The flight had a two-hour delay.', 'Travel', 'A2', 'noun', 'A period of waiting caused by something happening later than planned.', ARRAY['The flight had a two-hour delay.', 'We apologize for the delay.', 'Traffic caused a long delay.'], NULL, 'neutral', 'Travel'),
  ('en-vocab-v2-fever', 'en', 'Fever', 'Fiebre', '/ˈfiː.vɚ/', 'She has a fever and a cough.', 'Health', 'A2', 'noun', 'A body temperature higher than normal, usually from illness.', ARRAY['She has a fever and a cough.', 'His fever went down after the medicine.', 'A high fever needs a doctor.'], NULL, 'neutral', 'Health'),
  ('en-vocab-v2-hobby', 'en', 'Hobby', 'Pasatiempo', '/ˈhɑː.bi/', 'Painting is my favorite hobby.', 'Daily Life', 'A2', 'noun', 'An activity done regularly for pleasure.', ARRAY['Painting is my favorite hobby.', 'What''s your hobby outside of work?', 'Photography became a serious hobby for him.'], NULL, 'neutral', 'Hobbies'),
  ('en-vocab-v2-shift', 'en', 'Shift', 'Turno', '/ʃɪft/', 'I work the night shift on weekends.', 'Work', 'A2', 'noun', 'A scheduled period of work.', ARRAY['I work the night shift on weekends.', 'Can you cover my shift tomorrow?', 'Her shift starts at 9 AM.'], NULL, 'neutral', 'Work'),
  ('en-vocab-v2-classmate', 'en', 'Classmate', 'Compañero/a de clase', '/ˈklæs.meɪt/', 'She studies with a classmate every week.', 'Education', 'A2', 'noun', 'A person in the same class as you.', ARRAY['She studies with a classmate every week.', 'My classmate helped me with the homework.', 'We used to be classmates in high school.'], NULL, 'neutral', 'Education'),
  ('en-vocab-v2-get-along-with', 'en', 'Get along with', 'Llevarse bien con', '/ɡet əˈlɒŋ wɪð/', 'I get along with my coworkers.', 'Relationships', 'A2', 'phrasal verb', 'To have a friendly relationship with someone.', ARRAY['I get along with my coworkers.', 'She doesn''t get along with her sister.', 'They get along really well.'], NULL, 'neutral', 'Relationships'),
  ('en-vocab-v2-forecast', 'en', 'Forecast', 'Pronóstico', '/ˈfɔːr.kæst/', 'The forecast says it will rain tomorrow.', 'Nature', 'A2', 'noun', 'A prediction of future weather.', ARRAY['The forecast says it will rain tomorrow.', 'Check the forecast before the trip.', 'The weather forecast was wrong again.'], NULL, 'neutral', 'Weather'),
  ('en-vocab-v2-charger', 'en', 'Charger', 'Cargador', '/ˈtʃɑːr.dʒɚ/', 'I forgot my phone charger at home.', 'Technology', 'A2', 'noun', 'A device used to recharge a battery.', ARRAY['I forgot my phone charger at home.', 'Can I borrow your charger?', 'The charger stopped working.'], NULL, 'neutral', 'Technology'),
  ('en-vocab-v2-crowded', 'en', 'Crowded', 'Concurrido/lleno de gente', '/ˈkraʊ.dɪd/', 'The bus was too crowded to move.', 'Daily Life', 'A2', 'adjective', 'Full of people.', ARRAY['The bus was too crowded to move.', 'Downtown gets crowded on weekends.', 'The restaurant was crowded at lunchtime.'], NULL, 'neutral', 'City'),
  ('en-vocab-v2-figure-out', 'en', 'Figure out', 'Descifrar / entender', '/ˈfɪɡ.jɚ aʊt/', 'I finally figured out how the app works.', 'Technology', 'A2', 'phrasal verb', 'To understand or solve something after thinking about it.', ARRAY['I finally figured out how the app works.', 'Can you figure out what''s wrong with the printer?', 'She figured out the answer on her own.'], NULL, 'neutral', 'Common Phrasal Verbs'),
  ('en-vocab-v2-give-up', 'en', 'Give up', 'Rendirse / dejar de hacer algo', '/ɡɪv ʌp/', 'Don''t give up on your goals.', 'Daily Life', 'A2', 'phrasal verb', 'To stop trying to do something.', ARRAY['Don''t give up on your goals.', 'He gave up smoking last year.', 'She almost gave up during the exam.'], NULL, 'neutral', 'Common Phrasal Verbs')
